// has — there is then no evaluation to serialise with.
func (q *Queries) LockHostEvalCursor(ctx context.Context, arg LockHostEvalCursorParams) (int64, error) {
	result, err := q.db.Exec(ctx, lockHostEvalCursor, arg.OrgID, arg.HostID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markHostDirtyNow = `-- name: MarkHostDirtyNow :exec
UPDATE check_eval_cursor SET dirty_at = clock_timestamp()
WHERE org_id = $1 AND host_id = $2
`

type MarkHostDirtyNowParams struct {
	OrgID  uuid.UUID `json:"org_id"`
	HostID uuid.UUID `json:"host_id"`
}

// The forget's own evaluation mark: the item's states are gone, so the
// host's roll-up (check_host_states) is stale until the next evaluation.
// clock_timestamp() rather than MarkHostDirty's now(): it runs after
// LockHostEvalCursor may have waited for an evaluation, whose
// evaluated_at is its own transaction's start — possibly later than this
// transaction's now(), which would leave the host looking evaluated.
func (q *Queries) MarkHostDirtyNow(ctx context.Context, arg MarkHostDirtyNowParams) error {
	_, err := q.db.Exec(ctx, markHostDirtyNow, arg.OrgID, arg.HostID)
	return err
}

const seriesForHost = `-- name: SeriesForHost :many
SELECT time_bucket(make_interval(secs => $1::double precision), at)::timestamptz AS bucket,
       avg(value)::double precision AS value
FROM check_samples
WHERE org_id = $2 AND host_id = $3 AND check_key = $4
  AND item = $5 AND metric = $6
  AND at >= $7 AND at < $8
  AND value IS NOT NULL
  -- internal/checks.MaxAbsValue (backlog 3.11c): ingest refuses a value
  -- beyond it, but one stored before may be NaN, ±Infinity or 1e200, and
  -- avg() overflows on 1e200 next to any other sample, failing the route.
  -- NaN sorts above every number in PostgreSQL, so BETWEEN leaves it out.
  AND value BETWEEN -1e100 AND 1e100
GROUP BY bucket
ORDER BY bucket
`

type SeriesForHostParams struct {
	BucketSeconds float64   `json:"bucket_seconds"`
	OrgID         uuid.UUID `json:"org_id"`
	HostID        uuid.UUID `json:"host_id"`
	CheckKey      string    `json:"check_key"`
	Item          string    `json:"item"`
	Metric        string    `json:"metric"`
	FromAt        time.Time `json:"from_at"`
	ToAt          time.Time `json:"to_at"`
}

type SeriesForHostRow struct {
	Bucket time.Time `json:"bucket"`
	Value  float64   `json:"value"`
}

// One metric's samples for one host, downsampled server-side: bucket_seconds
// is the caller's own (to-from)/buckets, turned into an interval through
// make_interval rather than string-formatted into the query text, which
// keeps this a plain parameterized statement.
//
// `value IS NOT NULL` is load-bearing, not tidiness. avg() does skip NULL
// rows, but a BUCKET that contains nothing but label rows still forms, and
// avg() over it is NULL, which the generated scan refuses ("cannot scan
// NULL into *float64") — a 500 on a shipped route, reachable from two
// ordinary ingests on the seeded service check (a state reading, then a
// collection failure; filed as backlog 3.29 and closed here, pinned by
// internal/api's TestHostMetricsAfterACollectionErrorIsAnEmptySeries).
// Filtering the rows out instead means such a bucket never forms at all,
// so the answer is an honest empty series. The caller refuses a metric it can SEE is discrete
// before reaching here; this is what covers the case it cannot see,
// where the only current row is an error carrying neither value nor label.
func (q *Queries) SeriesForHost(ctx context.Context, arg SeriesForHostParams) ([]SeriesForHostRow, error) {
	rows, err := q.db.Query(ctx, seriesForHost,
		arg.BucketSeconds,
		arg.OrgID,
		arg.HostID,
		arg.CheckKey,
		arg.Item,
		arg.Metric,
		arg.FromAt,
		arg.ToAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SeriesForHostRow
	for rows.Next() {
		var i SeriesForHostRow
		if err := rows.Scan(&i.Bucket, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateCheckCurrent = `-- name: UpdateCheckCurrent :execrows
UPDATE check_current SET
  value = $1, label = $2, at = $3, error = $4
WHERE org_id = $5 AND host_id = $6
  AND check_key = $7 AND item = $8 AND metric = $9
`

type UpdateCheckCurrentParams struct {
	Value    *float64  `json:"value"`
	Label    *string   `json:"label"`
	At       time.Time `json:"at"`
	Error    *string   `json:"error"`
	OrgID    uuid.UUID `json:"org_id"`
	HostID   uuid.UUID `json:"host_id"`
	CheckKey string    `json:"check_key"`
	Item     string    `json:"item"`
	Metric   string    `json:"metric"`
}

// The existing-tuple half of ingest (backlog 7.57): replaces an existing
// row wholesale, exactly like UpsertCheckCurrent's conflict arm, and
// reports 0 rows for a tuple the host has never reported. Only a tuple
// that is new to the host counts against the per-host tuple cap, so ingest
// tries this first and reaches for the cap and UpsertCheckCurrent only on
// 0. The primary key's leading host_id makes it one index probe.
func (q *Queries) UpdateCheckCurrent(ctx context.Context, arg UpdateCheckCurrentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCheckCurrent,
		arg.Value,
		arg.Label,
		arg.At,
		arg.Error,
		arg.OrgID,
		arg.HostID,
		arg.CheckKey,
		arg.Item,
		arg.Metric,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateCheckDefinition = `-- name: UpdateCheckDefinition :one
UPDATE check_definitions
SET key = $1, plugin = $2, params = $3::jsonb,
    interval_seconds = $4, enabled = $5,
    binding_kind = $6, group_id = $7, host_id = $8,
    updated_at = now()
WHERE org_id = $9 AND id = $10
RETURNING id, org_id, key, plugin, params, interval_seconds, enabled, origin, binding_kind, group_id, host_id, created_by, created_at, updated_at, shared_definition_id
`

type UpdateCheckDefinitionParams struct {
	Key             string      `json:"key"`
	Plugin          string      `json:"plugin"`
	Params          []byte      `json:"params"`
	IntervalSeconds int32       `json:"interval_seconds"`
	Enabled         bool        `json:"enabled"`
	BindingKind     string      `json:"binding_kind"`
	GroupID         pgtype.UUID `json:"group_id"`
	HostID          pgtype.UUID `json:"host_id"`
	OrgID           uuid.UUID   `json:"org_id"`
	ID              uuid.UUID   `json:"id"`
}

// Full replace of every mutable column, exactly like UpdateMonitoringGroup;
// origin is deliberately absent from the SET list — it never changes after
// creation, so the service carries it through unchanged rather than this
// query being able to touch it.
func (q *Queries) UpdateCheckDefinition(ctx context.Context, arg UpdateCheckDefinitionParams) (CheckDefinition, error) {
	row := q.db.QueryRow(ctx, updateCheckDefinition,
		arg.Key,
		arg.Plugin,
		arg.Params,
		arg.IntervalSeconds,
		arg.Enabled,
		arg.BindingKind,
		arg.GroupID,
		arg.HostID,
		arg.OrgID,
		arg.ID,
	)
	var i CheckDefinition
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.Key,
		&i.Plugin,
		&i.Params,
		&i.IntervalSeconds,
		&i.Enabled,
		&i.Origin,
		&i.BindingKind,
		&i.GroupID,
		&i.HostID,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SharedDefinitionID,
	)
	return i, err
}

const updateMonitoringGroup = `-- name: UpdateMonitoringGroup :one
UPDATE monitoring_groups
SET name = $1, selector = $2, priority = $3, updated_at = now()
WHERE org_id = $4 AND id = $5
RETURNING id, org_id, name, selector, priority, created_at, updated_at
`

type UpdateMonitoringGroupParams struct {
	Name     string    `json:"name"`
	Selector string    `json:"selector"`
	Priority int32     `json:"priority"`
	OrgID    uuid.UUID `json:"org_id"`
	ID       uuid.UUID `json:"id"`
}

// Full replace of every mutable column; org_id in the WHERE clause is what
// actually makes "the group must belong to the org" enforceable from a
// plain application connection (see hosts.sql's GetZone/GetHost for the
// same reasoning about RLS not being the only guard).
func (q *Queries) UpdateMonitoringGroup(ctx context.Context, arg UpdateMonitoringGroupParams) (MonitoringGroup, error) {
	row := q.db.QueryRow(ctx, updateMonitoringGroup,
		arg.Name,
		arg.Selector,
		arg.Priority,
		arg.OrgID,
		arg.ID,
	)
	var i MonitoringGroup
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.Name,
		&i.Selector,
		&i.Priority,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertCheckCurrent = `-- name: UpsertCheckCurrent :exec
INSERT INTO check_current (org_id, host_id, check_key, item, metric, value, label, at, error)
VALUES (
  $1, $2, $3, $4, $5,
  $6, $7, $8, $9
)
ON CONFLICT (host_id, check_key, item, metric) DO UPDATE SET
  value = EXCLUDED.value, label = EXCLUDED.label, at = EXCLUDED.at, error = EXCLUDED.error
`

type UpsertCheckCurrentParams struct {
	OrgID    uuid.UUID `json:"org_id"`
	HostID   uuid.UUID `json:"host_id"`
	CheckKey string    `json:"check_key"`
	Item     string    `json:"item"`
	Metric   string    `json:"metric"`
	Value    *float64  `json:"value"`
	Label    *string   `json:"label"`
	At       time.Time `json:"at"`
	Error    *string   `json:"error"`
}

// Replaces the (host_id, check_key, item, metric) row wholesale: value,
// label, at and error together, never a partial update — an error
// observation must clear a previous value/label (and vice versa), which a
// SET list that only touched some columns could leave stale.
func (q *Queries) UpsertCheckCurrent(ctx context.Context, arg UpsertCheckCurrentParams) error {
	_, err := q.db.Exec(ctx, upsertCheckCurrent,
		arg.OrgID,
		arg.HostID,
		arg.CheckKey,
		arg.Item,
		arg.Metric,
		arg.Value,
		arg.Label,
		arg.At,
		arg.Error,
	)
	return err
}
